-- Approach A: Set-based
UPDATE Users SET Status = 'Inactive' 
WHERE LastLogin < DATEADD(year, -1, GETDATE());

-- Approach B: Procedural (Cursor/Loop)
DECLARE @UserId INT;
DECLARE cur CURSOR FOR SELECT Id FROM Users WHERE LastLogin < ...
OPEN cur;
FETCH NEXT FROM cur INTO @UserId;
WHILE @@FETCH_STATUS = 0
BEGIN
    UPDATE Users SET Status = 'Inactive' WHERE Id = @UserId;
    FETCH NEXT FROM cur INTO @UserId;
END
CLOSE cur; DEALLOCATE cur;

